{{-- A mailbox's folders in the sidebar (also sent when new messages come in: App\Events\RealtimeMailboxNewThread). --}}
@foreach (App\Misc\Sidebar::visibleFolders($sidebar_folders, $sidebar_current_folder_id, $sidebar_counts['folders']) as $sidebar_folder)
    @php $sidebar_count = $sidebar_counts['folders'][$sidebar_folder->id] ?? 0; @endphp
    <a href="{{ $sidebar_folder->url($sidebar_mailbox->id) }}" class="f-sidebar__item app-folder-link" @if ($sidebar_current_folder_id == $sidebar_folder->id) aria-current="page" @endif @if ($sidebar_count) aria-label="{{ __(':mailbox, :count unread', ['mailbox' => $sidebar_folder->getTypeName(), 'count' => $sidebar_count]) }}" @endif data-label-unread="{{ __(':mailbox, :count unread', ['mailbox' => $sidebar_folder->getTypeName(), 'count' => ':count']) }}" data-folder_id="{{ $sidebar_folder->id }}"@if ($sidebar_mailbox->id < 0) data-mailbox_id="{{ $sidebar_mailbox->id }}"@endif data-unread-count="{{ $sidebar_count }}"><x-dynamic-component :component="App\Misc\Sidebar::folderIcon($sidebar_folder)" class="f-icon" aria-hidden="true" /><span class="f-sidebar__identity">{{ $sidebar_folder->getTypeName() }}</span>@if ($sidebar_count)<span class="f-badge active-count">{{ $sidebar_count }}</span>@endif</a>
@endforeach
